={{ JSON.stringify({
  model: 'openai/gpt-5',
  messages: [
    {
      role: 'system',
      content: 'You are an expert GitHub Issue classifier. Classify the issue into exactly ONE type: "bug", "task", "feature", or "unknown".\n\nCriteria:\n- "bug": something is broken, crashing, throwing errors, regression.\n- "feature": request for new functionality, enhancement, improvement.\n- "task": question about setup, documentation update, configuration, general query.\n- "unknown": vague, empty, spam, or ambiguous text lacking details.\n\nCalculate confidence as a float between 0.0 and 1.0. If the issue lacks details, set confidence < 0.8.\n\nCRITICAL: Return ONLY a valid JSON object matching this schema:\n{"type": "bug"|"task"|"feature"|"unknown", "confidence": 0.95}'
    },
    {
      role: 'user',
      content: 'Title: ' + ($json.title || '') + '\n\nBody: ' + ($json.body || '')
    }
  ],
  temperature: 0.1
}) }}

parameters.jsCode:
const rawText = $json.choices[0].message.content.trim();
let result = { type: 'unknown', confidence: 0.5 };

try {
  // Strip markdown codeblocks if model returned ```json ... ```
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  const parsed = JSON.parse(cleaned);
  if (parsed.type && typeof parsed.confidence === 'number') {
    result.type = ['bug', 'task', 'feature', 'unknown'].includes(parsed.type.toLowerCase()) ? parsed.type.toLowerCase() : 'unknown';
    result.confidence = Math.min(1.0, Math.max(0.0, parsed.confidence));
  }
} catch (e) {
  // Fallback if parsing fails
  result = { type: 'unknown', confidence: 0.4 };
}

return [{ json: result }];
